import { CommonModule, Location } from '@angular/common';
import { Component } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ActivatedRoute, Router } from '@angular/router';
import { PermissionService } from '../../../../services/permission/permission.service';
import { userpermissionResponce } from '../../../../interfaces/permission.interface';
import { CommonfunctionService } from '../../../../../core/utility/commonfunction.service';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { UsercreationComponent } from '../../usercreation/usercreation.component';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { UserPermissionService } from '../../../../../shared/services/user-permission/user-permission.service';
interface Food {
  value: string;
  viewValue: string;
}
@Component({
  selector: 'app-userpermission',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, BadgeComponent, IconComponent, AvatarComponent, MatFormFieldModule, MatSelectModule,
    FormsModule, MatTooltipModule, MatDialogModule],
  templateUrl: './userpermission.component.html',
  styleUrl: './userpermission.component.scss'
})
export class UserpermissionComponent {
  foods: Food[] = [
    { value: '1000000000000', viewValue: 'Unlimited' },
    { value: '100000', viewValue: '100mb' },
    { value: '500000', viewValue: '500mb' },
    { value: '1000000', viewValue: '1gb' },
    { value: '100000000', viewValue: '100gb' },
  ];

  nCaseid: string;
  teamlist: userpermissionResponce[];
  isloading: boolean = false;
  userInfo;
  constructor(private cf: CommonfunctionService, private dialog: MatDialog, private route: ActivatedRoute,
    private permissionS: PermissionService, private location: Location, private ss: SecureStorageService,
  private userPermissions: UserPermissionService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);

  }


  async ngOnInit() {
    this.userInfo = await this.ss.getUserInfo();
    this.getTeamList();
  }

  editPermission(x) {
    if (!this.userInfo.isAdmin && this.userInfo.nUserid == x.nUserid) { return }
    this.cf.gotoEncoduri('/permission/editpermission', { id: this.nCaseid, user: x.nUserid, fnm: x.cFname, lnm: x.cLname, });
  }


  getTeamList() {
    this.isloading = true;
    this.permissionS.userpermissionList(this.nCaseid).then(res => {
      this.teamlist = res;
      this.isloading = false;
    });
  }

  manageUser(x) {
    if (!this.userInfo.isAdmin && this.userInfo.nUserid == x.nUserid) { return }
    x.cStatus = x.cStatus == 'A' ? 'I' : 'A';
    this.permissionS.manageUser({ nCaseid: this.nCaseid, nUserid: x.nUserid, cStatus: x.cStatus });
  }

  manageQuota(x) {
    this.permissionS.manageQuota({ nCaseid: this.nCaseid, nUserid: x.nUserid, nQuota: parseFloat(x.nQuota) });
  }


  close() {
    this.location.back();
  }

  editUser(x) {

    const dialogRef = this.dialog.open(UsercreationComponent, {
      width: 'fit-content',
      height: 'fit-content',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      data: {
        nCaseid: this.nCaseid,
        nUserid: x && x.nUserid ? x.nUserid : null
      }
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result && result["isSave"]) {
        if (result["delete"]) {
          var team: userpermissionResponce = this.teamlist.find(team => team.nTeamid = x.nTeamid);
          var ind = team.users.findIndex(user => user.nUserid == x.nUserid);
          team.users.splice(ind, 1);
          if (!team.users.length) {
            ind = this.teamlist.findIndex(team => team.nTeamid = x.nTeamid);
            this.teamlist.splice(ind, 1);
          }
          return;
        }
        this.getTeamList();

        var values = dialogRef.componentInstance.userForm.value;
        x.cFname = values.cFname;
        x.cLname = values.cLname;

        if (x.nTeamid != values.nTeamid) {
          x.nTeamid = values.nTeamid;
          var team: userpermissionResponce = this.teamlist.find(team => team.nTeamid = x.nTeamid);
          var ind = team.users.findIndex(user => user.nUserid == x.nUserid);
          this.teamlist.find(team => team.nTeamid = values.nTeamid).users.push(team.users[ind]);
          team.users.splice(ind, 1);
          if (!team.users.length) {
            ind = this.teamlist.findIndex(team => team.nTeamid = x.nTeamid);
            this.teamlist.splice(ind, 1);
          }
        }
        //dialogRef.componentInstance.userForm.value
      }
    })
  }
}
